import{_ as a,o as t,c as s,ag as n}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"IP Addressing, NAT, DHCP, CGNAT, MAC Addresses, and Internet Reachability","description":"","frontmatter":{},"headers":[],"relativePath":"networking/ip_addressing/IpAddressingNatDhcp.md","filePath":"networking/ip_addressing/IpAddressingNatDhcp.md"}'),i={name:"networking/ip_addressing/IpAddressingNatDhcp.md"};function o(r,e,d,c,l,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="ip-addressing-nat-dhcp-cgnat-mac-addresses-and-internet-reachability" tabindex="-1">IP Addressing, NAT, DHCP, CGNAT, MAC Addresses, and Internet Reachability <a class="header-anchor" href="#ip-addressing-nat-dhcp-cgnat-mac-addresses-and-internet-reachability" aria-label="Permalink to &quot;IP Addressing, NAT, DHCP, CGNAT, MAC Addresses, and Internet Reachability&quot;">​</a></h1><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="two-independent-classifications-of-ip-addresses" tabindex="-1">Two independent classifications of IP addresses <a class="header-anchor" href="#two-independent-classifications-of-ip-addresses" aria-label="Permalink to &quot;Two independent classifications of IP addresses&quot;">​</a></h3><p>A common wrong assumption: public IP = static IP, private IP = dynamic IP. Incorrect — these are two completely different dimensions.</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td>Reachability</td><td>Public</td><td>Reachable from the internet</td></tr><tr><td>Reachability</td><td>Private</td><td>Reachable only within a private network</td></tr><tr><td>Assignment</td><td>Static</td><td>Does not change</td></tr><tr><td>Assignment</td><td>Dynamic</td><td>Can change over time</td></tr></tbody></table><p>Any combination is possible:</p><table tabindex="0"><thead><tr><th>Reachability</th><th>Assignment</th><th>Example</th></tr></thead><tbody><tr><td>Public</td><td>Static</td><td>Load balancer, public-facing server</td></tr><tr><td>Public</td><td>Dynamic</td><td>Home broadband connection</td></tr><tr><td>Private</td><td>Static</td><td>Database server in a VPC</td></tr><tr><td>Private</td><td>Dynamic</td><td>Laptop, phone, Kubernetes Pod</td></tr></tbody></table><h3 id="public-ips" tabindex="-1">Public IPs <a class="header-anchor" href="#public-ips" aria-label="Permalink to &quot;Public IPs&quot;">​</a></h3><p>A public IP is globally routable — anyone on the internet can send traffic to it.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.company.com → 13.233.50.120</span></span></code></pre></div><p>Common usage: public load balancers, public APIs, internet-facing services.</p><h3 id="private-ips" tabindex="-1">Private IPs <a class="header-anchor" href="#private-ips" aria-label="Permalink to &quot;Private IPs&quot;">​</a></h3><p>Private IPs are used inside local networks and are not routable on the public internet. The reserved private ranges:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10.0.0.0/8</span></span>
<span class="line"><span>172.16.0.0 – 172.31.255.255</span></span>
<span class="line"><span>192.168.0.0/16</span></span></code></pre></div><p>A typical home network: laptop <code>192.168.1.2</code>, phone <code>192.168.1.3</code>, router <code>192.168.1.1</code>. These addresses only have meaning inside that network.</p><h3 id="static-ips" tabindex="-1">Static IPs <a class="header-anchor" href="#static-ips" aria-label="Permalink to &quot;Static IPs&quot;">​</a></h3><p>A static IP remains fixed — a database at <code>10.0.1.20</code> today is still <code>10.0.1.20</code> next month. Used when other systems need a predictable address: databases, DNS servers, VPN servers, load balancers.</p><h3 id="dynamic-ips" tabindex="-1">Dynamic IPs <a class="header-anchor" href="#dynamic-ips" aria-label="Permalink to &quot;Dynamic IPs&quot;">​</a></h3><p>Assigned automatically and may change — <code>192.168.1.10</code> today, <code>192.168.1.15</code> tomorrow. Typical for employee laptops, phones, home devices, Kubernetes Pods, cloud VMs.</p><h2 id="dhcp" tabindex="-1">DHCP <a class="header-anchor" href="#dhcp" aria-label="Permalink to &quot;DHCP&quot;">​</a></h2><p>DHCP (Dynamic Host Configuration Protocol) lets a device join a network and automatically receive an IP address. Without it, every phone/laptop/TV would need manual IP configuration.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phone joins WiFi → requests address → router assigns IP</span></span></code></pre></div><p>In home networks the router <strong>is</strong> the DHCP server, and it keeps a lease table mapping devices to assigned addresses.</p><h3 id="dhcp-leases" tabindex="-1">DHCP leases <a class="header-anchor" href="#dhcp-leases" aria-label="Permalink to &quot;DHCP leases&quot;">​</a></h3><p>A device is identified by its MAC address (<code>AA:BB:CC:DD:EE:FF</code>); the router assigns an IP (<code>192.168.1.10</code>) and stores the MAC → IP mapping for some lease duration.</p><p>Important: the IP is <strong>not</strong> permanently tied to the MAC. The DHCP server is simply remembering &quot;this MAC currently owns this IP&quot; — the mapping can change later.</p><h2 id="why-ipv4-addresses-are-scarce" tabindex="-1">Why IPv4 addresses are scarce <a class="header-anchor" href="#why-ipv4-addresses-are-scarce" aria-label="Permalink to &quot;Why IPv4 addresses are scarce&quot;">​</a></h2><p>IPv4 has 2^32 ≈ 4.3 billion possible addresses. The world has more people than IPv4 addresses, and far more devices. This shortage is one of the primary reasons NAT exists.</p><h2 id="nat-network-address-translation" tabindex="-1">NAT (Network Address Translation) <a class="header-anchor" href="#nat-network-address-translation" aria-label="Permalink to &quot;NAT (Network Address Translation)&quot;">​</a></h2><h3 id="the-problem-nat-solves" tabindex="-1">The problem NAT solves <a class="header-anchor" href="#the-problem-nat-solves" aria-label="Permalink to &quot;The problem NAT solves&quot;">​</a></h3><p>Inside a home network, laptop <code>192.168.1.2</code>, phone <code>192.168.1.3</code>, TV <code>192.168.1.4</code> are private IPs. Google cannot route traffic directly back to <code>192.168.1.2</code> — private addresses are not globally routable.</p><h3 id="what-nat-does" tabindex="-1">What NAT does <a class="header-anchor" href="#what-nat-does" aria-label="Permalink to &quot;What NAT does&quot;">​</a></h3><p>The laptop sends a request with source <code>192.168.1.2</code>, destination <code>google.com</code>. The router rewrites the source to the public IP:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source 192.168.1.2  →  Source 49.204.10.15  →  google.com</span></span></code></pre></div><p>Google sees <code>49.204.10.15</code>, not <code>192.168.1.2</code>. The router is effectively representing all local devices to the outside world.</p><h3 id="nat-uses-ports-not-just-ip-addresses" tabindex="-1">NAT uses ports, not just IP addresses <a class="header-anchor" href="#nat-uses-ports-not-just-ip-addresses" aria-label="Permalink to &quot;NAT uses ports, not just IP addresses&quot;">​</a></h3><p>This is the crucial detail. When the laptop opens a connection from <code>192.168.1.10:54321</code>, the router may translate it to <code>49.204.10.15:60001</code> and store the mapping in its NAT table:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>49.204.10.15:60001  →  192.168.1.10:54321</span></span></code></pre></div><p>When the response returns to <code>49.204.10.15:60001</code>, the router looks up the mapping and forwards it correctly. This is how thousands of simultaneous connections share one public IP.</p><h2 id="cgnat-carrier-grade-nat" tabindex="-1">CGNAT (Carrier-Grade NAT) <a class="header-anchor" href="#cgnat-carrier-grade-nat" aria-label="Permalink to &quot;CGNAT (Carrier-Grade NAT)&quot;">​</a></h2><h3 id="nat-on-top-of-nat" tabindex="-1">NAT on top of NAT <a class="header-anchor" href="#nat-on-top-of-nat" aria-label="Permalink to &quot;NAT on top of NAT&quot;">​</a></h3><p>Many ISPs do not give each customer a unique public IP — they add their own NAT layer:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phone            192.168.1.10</span></span>
<span class="line"><span>  ↓ Home router NAT</span></span>
<span class="line"><span>ISP private IP   100.64.10.25</span></span>
<span class="line"><span>  ↓ ISP CGNAT</span></span>
<span class="line"><span>Public IP        49.204.10.15</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Internet</span></span></code></pre></div><p>Three addresses can exist for one device: <code>192.168.1.10</code>, <code>100.64.10.25</code>, <code>49.204.10.15</code>. CGNAT is effectively NAT → NAT → Internet.</p><h3 id="isp-internal-addressing" tabindex="-1">ISP internal addressing <a class="header-anchor" href="#isp-internal-addressing" aria-label="Permalink to &quot;ISP internal addressing&quot;">​</a></h3><p>ISPs maintain internal address space for customer routers — e.g. Customer A <code>100.64.1.10</code>, Customer B <code>100.64.1.11</code>, Customer C <code>100.64.1.12</code> — all ultimately sharing <code>49.204.10.15</code> as the public-facing IP.</p><h2 id="mac-addresses" tabindex="-1">MAC addresses <a class="header-anchor" href="#mac-addresses" aria-label="Permalink to &quot;MAC addresses&quot;">​</a></h2><h3 id="what-a-mac-address-is" tabindex="-1">What a MAC address is <a class="header-anchor" href="#what-a-mac-address-is" aria-label="Permalink to &quot;What a MAC address is&quot;">​</a></h3><p>MAC addresses identify network interfaces, e.g. <code>A4:5E:60:2B:11:9C</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MAC = device identity</span></span>
<span class="line"><span>IP  = current network location</span></span></code></pre></div><p>A device can change locations; its MAC generally remains the same.</p><h3 id="ip-vs-mac" tabindex="-1">IP vs MAC <a class="header-anchor" href="#ip-vs-mac" aria-label="Permalink to &quot;IP vs MAC&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>IP Address</th><th>MAC Address</th></tr></thead><tbody><tr><td>Purpose</td><td>Network location</td><td>Device/interface identity</td></tr><tr><td>Can change</td><td>Yes</td><td>Usually no</td></tr><tr><td>Used across internet</td><td>Yes</td><td>No</td></tr><tr><td>Used in local network</td><td>Yes</td><td>Yes</td></tr></tbody></table><p>A useful mental model: MAC = Aadhaar number, IP = hotel room number. You can move rooms; your identity remains the same.</p><h3 id="why-internet-routing-uses-ips-not-macs" tabindex="-1">Why internet routing uses IPs, not MACs <a class="header-anchor" href="#why-internet-routing-uses-ips-not-macs" aria-label="Permalink to &quot;Why internet routing uses IPs, not MACs&quot;">​</a></h3><p>Packets travel through many routers (laptop → home router → ISP router → Google router → Google server). MAC addresses are replaced at <strong>every hop</strong>; IP addresses remain the routing identifier — therefore internet routing uses IPs.</p><h3 id="are-mac-addresses-unique" tabindex="-1">Are MAC addresses unique? <a class="header-anchor" href="#are-mac-addresses-unique" aria-label="Permalink to &quot;Are MAC addresses unique?&quot;">​</a></h3><p>Manufacturers receive allocated MAC ranges; the first portion identifies the vendor. A MAC is 48 bits → 2^48 ≈ 281 trillion possibilities. In theory every MAC should be unique.</p><h3 id="can-mac-addresses-be-spoofed" tabindex="-1">Can MAC addresses be spoofed? <a class="header-anchor" href="#can-mac-addresses-be-spoofed" aria-label="Permalink to &quot;Can MAC addresses be spoofed?&quot;">​</a></h3><p>Yes. A MAC address is not a secure identity — devices can intentionally present a different MAC. MAC uniqueness is an operational convention, not a security guarantee.</p><h2 id="how-tracing-works" tabindex="-1">How tracing works <a class="header-anchor" href="#how-tracing-works" aria-label="Permalink to &quot;How tracing works&quot;">​</a></h2><p>If websites only see public IPs, how can users be traced? A website logs the public IP + timestamp (<code>49.204.10.15</code> at <code>10:35:12 PM</code>). ISP logs can map that back through CGNAT to the internal address (<code>100.64.1.10</code>) and the customer account; router records can further map to the local device (<code>192.168.1.10</code>) and potentially its MAC address.</p><p>The critical information is: public IP, timestamp, and — especially under CGNAT — often the port number.</p><h2 id="websites-and-dynamic-ips" tabindex="-1">Websites and dynamic IPs <a class="header-anchor" href="#websites-and-dynamic-ips" aria-label="Permalink to &quot;Websites and dynamic IPs&quot;">​</a></h2><h3 id="can-websites-use-dynamic-ips" tabindex="-1">Can websites use dynamic IPs? <a class="header-anchor" href="#can-websites-use-dynamic-ips" aria-label="Permalink to &quot;Can websites use dynamic IPs?&quot;">​</a></h3><p>Yes — many modern systems do. The key reason this works is DNS: <code>mywebsite.com</code> can point to <code>54.10.10.10</code> today and <code>18.20.30.40</code> tomorrow. DNS is simply updated; users keep accessing the hostname without knowing the underlying IP changed.</p><h3 id="why-interviewers-still-talk-about-static-ips" tabindex="-1">Why interviewers still talk about static IPs <a class="header-anchor" href="#why-interviewers-still-talk-about-static-ips" aria-label="Permalink to &quot;Why interviewers still talk about static IPs&quot;">​</a></h3><p>Historically servers commonly used static IPs. Modern cloud systems look like:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User → DNS → Load Balancer → Auto-scaled Servers</span></span></code></pre></div><p>Backend servers may have dynamic private IPs and be created/destroyed continuously. Only the externally visible entry point needs to remain stable.</p><h3 id="database-servers-and-private-static-ips" tabindex="-1">Database servers and private static IPs <a class="header-anchor" href="#database-servers-and-private-static-ips" aria-label="Permalink to &quot;Database servers and private static IPs&quot;">​</a></h3><p>Typical architecture:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Internet → Load Balancer → Application Servers → Database (10.0.1.20)</span></span></code></pre></div><p>The database is <strong>private</strong> (not internet reachable) and <strong>static</strong> (predictable for applications). This combination is common in production systems.</p><h2 id="gotchas-trick-questions" tabindex="-1">Gotchas / Trick questions <a class="header-anchor" href="#gotchas-trick-questions" aria-label="Permalink to &quot;Gotchas / Trick questions&quot;">​</a></h2><ol><li><strong>&quot;Public IP means static IP.&quot;</strong> Incorrect — a home broadband connection is often public + dynamic.</li><li><strong>&quot;Private IP means dynamic IP.&quot;</strong> Incorrect — a database server is often private + static.</li><li><strong>&quot;A website must have a static IP.&quot;</strong> Not necessarily — DNS allows the IPs behind a hostname to change.</li><li><strong>&quot;NAT only changes the source IP.&quot;</strong> Incomplete — NAT usually translates source IP <strong>and</strong> source port, maintaining a NAT table. Ports are what allow many simultaneous connections through one public IP.</li><li><strong>&quot;My router gets a public IP from the ISP.&quot;</strong> Sometimes — under CGNAT your router may receive <code>100.64.x.x</code>, which is not actually public; the ISP performs another NAT layer.</li><li><strong>&quot;MAC addresses are permanent and cannot be changed.&quot;</strong> Incorrect — MAC spoofing is common and supported by operating systems.</li><li><strong>&quot;A hacker can directly connect to a private database IP.&quot;</strong> Normally impossible from the internet. Breaches usually happen because an application server was compromised, a security group was misconfigured, VPN credentials were stolen, or the attacker moved laterally inside the network.</li><li><strong>&quot;A device&#39;s IP is permanently tied to its MAC.&quot;</strong> Incorrect — DHCP leases associate a MAC with an IP temporarily; the mapping can change later.</li></ol><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><h3 id="why-databases-are-usually-safer-behind-private-ips" tabindex="-1">Why databases are usually safer behind private IPs <a class="header-anchor" href="#why-databases-are-usually-safer-behind-private-ips" aria-label="Permalink to &quot;Why databases are usually safer behind private IPs&quot;">​</a></h3><p>Private IPs are not globally routable. An attacker on the public internet cannot directly send packets to <code>10.0.1.20</code> unless they first gain access to a system that already has connectivity to that network.</p><h3 id="mental-model-that-ties-everything-together" tabindex="-1">Mental model that ties everything together <a class="header-anchor" href="#mental-model-that-ties-everything-together" aria-label="Permalink to &quot;Mental model that ties everything together&quot;">​</a></h3><p>Three layers of identity:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DNS name     → human-friendly identifier</span></span>
<span class="line"><span>IP address   → network location</span></span>
<span class="line"><span>MAC address  → local hardware identity</span></span></code></pre></div><p>Modern distributed systems depend on DNS names instead of hardcoded IPs, because IPs frequently change in cloud environments.</p><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Are public/private and static/dynamic the same classification?</strong> A. No. Public/private describes reachability; static/dynamic describes whether the address changes.</p><p><strong>Q. What does DHCP do?</strong> A. Automatically assigns IP addresses and maintains lease mappings.</p><p><strong>Q. Why is NAT needed?</strong> A. Because private IPs are not internet-routable and IPv4 addresses are limited.</p><p><strong>Q. What does NAT actually translate?</strong> A. Typically both source IP and source port, tracked in a NAT table.</p><p><strong>Q. What is CGNAT?</strong> A. An ISP-level NAT layer sitting above your router&#39;s NAT — your router may get <code>100.64.x.x</code> instead of a real public IP.</p><p><strong>Q. What is the difference between IP and MAC?</strong> A. IP identifies network location; MAC identifies a local network interface. MACs are replaced at every routing hop; IPs persist end-to-end.</p><p><strong>Q. Can websites run on dynamic IPs?</strong> A. Yes. DNS allows hostname-to-IP mappings to change over time.</p>`,91)])])}const b=a(i,[["render",o]]);export{u as __pageData,b as default};
